mapper.insert:
insert into outbox_event (
    event_type, aggregate_type, aggregate_id, payload, status, retry_count,
    next_retry_at, lock_token, locked_at, processed_at, last_error,
    created_by, created_at, updated_at
) values (
    #{eventType}, #{aggregateType}, #{aggregateId}, #{payload}, #{status}, #{retryCount},
    #{nextRetryAt}, #{lockToken}, #{lockedAt}, #{processedAt}, #{lastError},
    #{createdBy}, #{createdAt}, #{updatedAt}
)

mapper.update:
update outbox_event
set status = 'PROCESSING',
    lock_token = #{lockToken},
    locked_at = #{lockedAt},
    updated_at = #{lockedAt}
where id = #{id}

mapper.delete:
delete from outbox_event
where status = 'DONE'
  and processed_at < #{processedBefore}
order by id asc
limit #{limit}
